// Import the Verus prelude so we can use `requires`, `ensures`, and quantifiers.
use verus::prelude::*;

#[requires(n >= 0)]
// The greedy decomposition count is exactly the sum of the quotients at each step.
#[ensures({
    let a = n / 100;
    let r1 = n % 100;
    let b = r1 / 20;
    let r2 = r1 % 20;
    let c = r2 / 10;
    let r3 = r2 % 10;
    let d = r3 / 5;
    let e = r3 % 5;
    result == a + b + c + d + e
})]
// The pieces actually sum back up to `n`.
#[ensures({
    let a = n / 100;
    let r1 = n % 100;
    let b = r1 / 20;
    let r2 = r1 % 20;
    let c = r2 / 10;
    let r3 = r2 % 10;
    let d = r3 / 5;
    let e = r3 % 5;
    100 * a + 20 * b + 10 * c + 5 * d + e == n
})]
// And no other combination of non‐negative counts can use fewer coins.
#[ensures(forall(|a: i8, b: i8, c: i8, d: i8, e: i8| 
    0 <= a && 0 <= b && 0 <= c && 0 <= d && 0 <= e &&
    100*a + 20*b + 10*c + 5*d + e == n
    ==> a + b + c + d + e >= result
))]
fn solve(n: i8) -> i8 {
    // Use a greedy decomposition with denominations 100, 20, 10, 5, and 1.
    let mut remaining = n;
    let mut count = 0;

    // 100-unit notes
    count += remaining / 100;
    remaining %= 100;

    // 20-unit notes
    count += remaining / 20;
    remaining %= 20;

    // 10-unit coins
    count += remaining / 10;
    remaining %= 10;

    // 5-unit coins
    count += remaining / 5;
    remaining %= 5;

    // 1-unit coins
    count += remaining;

    count
}

fn main() {
    let tests = [1, 6, 23, 125, 127];
    for &t in &tests {
        println!("Amount: {}, Min coins: {}", t, solve(t));
    }
}